#![allow(unused_imports)]
use vstd::prelude::*;
verus! {

    #[verifier(external_body)]
    pub fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject
        ensures x.len() > 0
        ensures y.len() > 0
        ensures res.well_formed()
        ensures res.shape.0 == x.len()
        ensures res.shape.1 == y.len()
        ensures forall |i: nat, j: nat|
            requires i < x.len() && j < y.len()
            ensures  res.get(i, j) == (x[i], y[j])
    {
        // Enforce the non‐emptiness so that res.well_formed() (m > 0 && n > 0) holds
        assert!(x.len() > 0, "x must be non‐empty");
        assert!(y.len() > 0, "y must be non‐empty");

        let m = x.len();
        let n = y.len();
        // Pre‐allocate exactly m * n slots
        let mut data = Vec::with_capacity(m * n);

        // Row‐major: for each i in 0..m and j in 0..n,
        // push the pair (x[i], y[j]).
        for &xi in x.iter() {
            for &yj in y.iter() {
                data.push((xi, yj));
            }
        }

        BroadcastObject {
            shape: (m, n),
            data,
        }
    }

} // verus!